      passed,
      message: passed ? "Conversion rate in valid range." : `Conversion rate ${rate} out of [0,1].`,
      details: { rate },
    };
  } catch (e) {
    return {
      passed: false,
      message: "Could not check conversion rate.",
      details: { error: e instanceof Error ? e.message : String(e) },
    };
  }
}

